      else throw new Error('Unsupported file type: '+p);
      if(result.length>20000)throw new Error('Too many input files');
    }
  }
  visit(root);return result;
}
function assertInput(value) {
  const resolved=path.resolve(value);
  if(!resolved.startsWith('/inputs/'))throw new Error('Input must be under /inputs');
  let current='/inputs';
  for(const part of path.relative('/inputs',resolved).split(path.sep)){
    current=path.join(current,part);
    if(fs.lstatSync(current).isSymbolicLink())throw new Error('Symlink input rejected');
  }
