}
function relativeInput(value) {
  if(typeof value!=='string'||!value||path.isAbsolute(value)||value.includes('\\')||value.includes('\0'))throw new Error('Invalid relative path');
  const parts=value.split('/');
  if(parts.some(p=>p==='..'||p==='.'||p===''))throw new Error('Unsafe relative path: '+value);
  if(['original','report','.git'].includes(parts[0]))throw new Error('Protected path: '+value);
