}
function copyTree(source,dest) {
  listFiles(source);fs.cpSync(source,dest,{recursive:true,dereference:false,preserveTimestamps:true});
}
function removeOutputs(folder) {
  if(!fs.existsSync(folder))return;
  for(const name of fs.readdirSync(folder)){
    const numeric=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(name);
    if((numeric&&Number(name)!==0)||name.startsWith('log.')||/^processor\d+$/.test(name)||['postProcessing','VTK'].includes(name))fs.rmSync(path.join(folder,name),{recursive:true,force:true});
